    'file_read_lines': (a) => _readLines(a['path'] as String),
    'file_write_lines': (a) => _writeLines(a['path'] as String, a['lines']),
    'file_append': (a) => _append(a['path'] as String, a['content'] as String),
    'file_info': (a) => _info(a['path'] as String),
